import { Component } from '@angular/core';

@Component({
  selector: 'app-qr-list',
  templateUrl: './qr-list.component.html',
  styleUrls: ['./qr-list.component.scss']
})
export class QrListComponent {

}
<p>qr-list works!</p>
<qrcode
  [qrdata]="'abhimanyu'"
  [width]="256"
  [errorCorrectionLevel]="'M'"
></qrcode>
